  audioSettings.prepend(sensitivity);audioSettings.prepend(noise);audioSettings.prepend(activation);
  right.append(membersPanel);setupSettings(audioSettings);
  const chatButton=btn('💬',()=>{chatOpen=!chatOpen;renderApp()},'chat-toggle hidden');chatButton.id='chat-toggle';chatButton.type='button';chatButton.title='Abrir chat do canal';chatButton.setAttribute('aria-label','Abrir chat do canal');$('channel-title').after(chatButton);
  const menuButton=btn('☰',()=>{const app=$('app');const expanded=!app.classList.contains('mobile-nav-open');app.classList.toggle('mobile-nav-open',expanded);app.classList.remove('mobile-members-open');menuButton.setAttribute('aria-expanded',String(expanded))},'mobile-menu-btn');menuButton.id='mobile-menu-btn';menuButton.title='Abrir comunidades e canais';menuButton.setAttribute('aria-label',menuButton.title);menuButton.setAttribute('aria-expanded','false');$('channel-icon').before(menuButton);
  const membersButton=btn('♙',()=>{const app=$('app');const expanded=!app.classList.contains('mobile-members-open');app.classList.toggle('mobile-members-open',expanded);app.classList.remove('mobile-nav-open');membersButton.setAttribute('aria-expanded',String(expanded))},'mobile-members-btn');membersButton.id='mobile-members-btn';membersButton.title='Mostrar membros';membersButton.setAttribute('aria-label',membersButton.title);membersButton.setAttribute('aria-expanded','false');$('top-description').after(membersButton);
  const scrim=document.createElement('button');scrim.id='mobile-drawer-scrim';scrim.className='mobile-drawer-scrim';scrim.type='button';scrim.title='Fechar painel';scrim.setAttribute('aria-label','Fechar painel');scrim.onclick=closeMobileDrawers;$('app').append(scrim);
  const savedNoise=localStorage.getItem('orbiter-noise-filter');const noiseEnabled=savedNoise!=='false';$<HTMLInputElement>('noise-filter').checked=noiseEnabled;void rtc.setNoiseSuppression(noiseEnabled);
