  $<HTMLInputElement>('noise-filter').onchange=async e=>{const enabled=(e.target as HTMLInputElement).checked;try{await rtc.setNoiseSuppression(enabled);localStorage.setItem('orbiter-noise-filter',String(enabled))}catch{$<HTMLInputElement>('noise-filter').checked=!enabled;toast('Este microfone não aceitou mudar o filtro durante a chamada. Desative e ative o microfone para aplicar.') }};
