function pttKeyLabel(code:string){if(code==='Space')return'Espaço';if(code.startsWith('Key'))return code.slice(3);if(code.startsWith('Digit'))return code.slice(5);return code}
function allowedPttKey(code:string){return /^(Key[A-Z]|Digit[0-9]|Space|F(?:[1-9]|1[0-2]))$/.test(code)}
function updatePttSettings(){$('ptt-key-row').classList.toggle('hidden',!pttMode);if(!choosingPttKey)$('ptt-key').textContent=pttKeyLabel(pttKeyCode)}
function updateMicButton(){const button=$('mic-btn'),on=rtc.micOn;button.classList.toggle('active',on);button.classList.toggle('transmitting',on&&rtc.micTransmitting);button.setAttribute('aria-pressed',String(on));button.querySelector('span')!.textContent=!on?'Ativar microfone':pttMode?(pttPressed?`Falando (${pttKeyLabel(pttKeyCode)})`:`Segure ${pttKeyLabel(pttKeyCode)} para falar`):'Desativar microfone'}
function releasePtt(){if(!pttPressed)return;pttPressed=false;if(pttMode)rtc.setMicTransmission(false);updateMicButton()}
window.addEventListener('keydown',event=>{if(choosingPttKey){event.preventDefault();event.stopImmediatePropagation();if(event.code==='Escape'){choosingPttKey=false;updatePttSettings();return}if(!allowedPttKey(event.code)){toast('Escolha uma letra, número, espaço ou F1–F12.');return}pttKeyCode=event.code;localStorage.setItem('orbiter-ptt-key',pttKeyCode);choosingPttKey=false;updatePttSettings();updateMicButton();return}
  if(!pttMode||!rtc.micOn||!activeChannel||event.code!==pttKeyCode||event.repeat||event.altKey||event.ctrlKey||event.metaKey)return;
  const target=event.target;if(target instanceof HTMLElement&&target.closest('input,textarea,select,[contenteditable="true"]'))return;
  event.preventDefault();pttPressed=true;rtc.setMicTransmission(true);updateMicButton()
},true);
window.addEventListener('keyup',event=>{if(event.code===pttKeyCode)releasePtt()},true);
window.addEventListener('blur',releasePtt);
document.addEventListener('visibilitychange',()=>{if(document.hidden)releasePtt()});
type Appearance={accent:string;background:string;panel:string;density:'comfortable'|'compact';fontSize:number;reducedMotion:boolean;showMembers:boolean};
const appearanceDefaults:Appearance={accent:'#8ee0c6',background:'#0b1720',panel:'#132833',density:'comfortable',fontSize:14,reducedMotion:false,showMembers:true};
function readAppearance():Appearance{try{const saved=JSON.parse(localStorage.getItem('orbiter-appearance')||'{}');return {...appearanceDefaults,...saved}}catch{return {...appearanceDefaults}}}
let appearance=readAppearance();
function applyAppearance(){const root=document.documentElement;root.style.setProperty('--orbiter-accent',appearance.accent);root.style.setProperty('--orbiter-background',appearance.background);root.style.setProperty('--orbiter-panel',appearance.panel);root.style.setProperty('--orbiter-font-size',`${appearance.fontSize}px`);document.body.classList.toggle('compact-ui',appearance.density==='compact');document.body.classList.toggle('reduce-motion',appearance.reducedMotion);document.body.classList.toggle('hide-members',!appearance.showMembers);localStorage.setItem('orbiter-appearance',JSON.stringify(appearance))}
function setupSettings(audioSettings:HTMLElement){
  const shell=document.createElement('div');shell.id='settings-modal';shell.className='settings-backdrop hidden';shell.innerHTML=`<div class="settings-window" role="dialog" aria-modal="true" aria-label="Configurações do Orbiter"><nav class="settings-nav" aria-label="Abas de configurações"><div class="settings-brand">✦ ORBITER</div><button id="settings-tab-profile" data-settings-tab="profile">Perfil</button><button id="settings-tab-colors" data-settings-tab="colors">Cores</button><button id="settings-tab-personalize" data-settings-tab="personalize">Personalização</button><button id="settings-tab-audio" data-settings-tab="audio">Áudio e vídeo</button><button id="settings-tab-account" data-settings-tab="account">Conta e sair</button></nav><div class="settings-main"><div class="settings-top"><div><small>SUAS PREFERÊNCIAS</small><h2 id="settings-heading">Perfil</h2></div><button id="settings-close" type="button" aria-label="Fechar configurações">✕</button></div><div class="settings-scroll"><section id="settings-panel-profile" class="settings-section"><p>Suas informações aparecem para os membros das comunidades.</p><form id="settings-profile-form"><label>Nome de exibição<input id="settings-display-name" maxlength="40" required></label><label>Descrição<textarea id="settings-bio" maxlength="300" rows="3"></textarea></label><label>Avatar (emoji ou texto curto)<input id="settings-avatar" maxlength="8"></label><label>Status<select id="settings-status"><option value="online">Online</option><option value="away">Ausente</option><option value="busy">Ocupado</option><option value="invisible">Invisível</option></select></label><button type="submit" class="primary settings-save">Salvar perfil</button></form></section><section id="settings-panel-colors" class="settings-section hidden"><p>Escolha as cores do Orbiter. Elas são salvas neste dispositivo.</p><div id="theme-presets" class="theme-presets"></div><div class="color-fields"><label>Cor de destaque<input id="theme-accent" type="color"></label><label>Fundo<input id="theme-background" type="color"></label><label>Painéis<input id="theme-panel" type="color"></label></div><button id="theme-reset" class="secondary" type="button">Restaurar cores originais</button></section><section id="settings-panel-personalize" class="settings-section hidden"><p>Ajuste o espaço e a leitura da interface.</p><label>Densidade<select id="settings-density"><option value="comfortable">Confortável</option><option value="compact">Compacta</option></select></label><label>Tamanho do texto <output id="font-size-value"></output><input id="settings-font-size" type="range" min="12" max="18"></label><label class="settings-check"><input id="settings-reduced-motion" type="checkbox"> Reduzir animações</label><label class="settings-check"><input id="settings-show-members" type="checkbox"> Mostrar lista de membros</label></section><section id="settings-panel-audio" class="settings-section hidden"><p>Escolha os dispositivos e teste microfone, som e câmera antes da chamada.</p><div id="audio-settings-panel"></div></section><section id="settings-panel-account" class="settings-section hidden"><p id="settings-account-name"></p><div class="account-exit"><h3>Sair da conta</h3><p>A sessão deste dispositivo será encerrada.</p><button id="settings-sign-out" type="button">Sair da conta</button></div></section></div></div></div>`;
  document.body.append(shell);$('audio-settings-panel').append(audioSettings);
  const labels:Record<string,string>={profile:'Perfil',colors:'Cores',personalize:'Personalização',audio:'Áudio e vídeo',account:'Conta e sair'};
  function selectTab(tab:string){for(const id of Object.keys(labels)){$(`settings-panel-${id}`).classList.toggle('hidden',id!==tab);$(`settings-tab-${id}`).classList.toggle('active',id===tab)}$('settings-heading').textContent=labels[tab]||'Configurações'}
  for(const button of Array.from(shell.querySelectorAll<HTMLButtonElement>('[data-settings-tab]')))button.onclick=()=>selectTab(button.dataset.settingsTab||'profile');
  $('settings-close').onclick=closeSettings;shell.addEventListener('click',event=>{if(event.target===shell)closeSettings()});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!shell.classList.contains('hidden'))closeSettings()});
  const presets:Array<[string,string,string,string]>=[['Orbiter','#8ee0c6','#0b1720','#132833'],['Azul','#7cb8ff','#10192e','#172846'],['Violeta','#c4a1ff','#1b172d','#2a2240'],['Âmbar','#f3bb76','#211a17','#35271f']];
  for(const [name,accent,background,panel] of presets){const button=btn(name,()=>{appearance={...appearance,accent,background,panel};applyAppearance();syncAppearanceControls()},'theme-preset');button.style.setProperty('--preset-color',accent);$('theme-presets').append(button)}
  for(const [id,key] of [['theme-accent','accent'],['theme-background','background'],['theme-panel','panel']] as const)$<HTMLInputElement>(id).oninput=event=>{appearance[key]=(event.target as HTMLInputElement).value;applyAppearance()};
  $('theme-reset').onclick=()=>{appearance={...appearance,...{accent:appearanceDefaults.accent,background:appearanceDefaults.background,panel:appearanceDefaults.panel}};applyAppearance();syncAppearanceControls()};
  $<HTMLSelectElement>('settings-density').onchange=event=>{appearance.density=(event.target as HTMLSelectElement).value as Appearance['density'];applyAppearance()};
  $<HTMLInputElement>('settings-font-size').oninput=event=>{appearance.fontSize=Number((event.target as HTMLInputElement).value);$('font-size-value').textContent=`${appearance.fontSize}px`;applyAppearance()};
  $<HTMLInputElement>('settings-reduced-motion').onchange=event=>{appearance.reducedMotion=(event.target as HTMLInputElement).checked;applyAppearance()};
  $<HTMLInputElement>('settings-show-members').onchange=event=>{appearance.showMembers=(event.target as HTMLInputElement).checked;applyAppearance()};
  $<HTMLFormElement>('settings-profile-form').onsubmit=async event=>{event.preventDefault();try{await request('profile_update',{displayName:$<HTMLInputElement>('settings-display-name').value,bio:$<HTMLTextAreaElement>('settings-bio').value,avatar:$<HTMLInputElement>('settings-avatar').value,status:$<HTMLSelectElement>('settings-status').value});toast('Perfil atualizado.')}catch(error){toast((error as Error).message)}};
  $('settings-sign-out').onclick=()=>{closeSettings();void signOut()};applyAppearance();selectTab('profile')
}
function syncAppearanceControls(){for(const [id,key] of [['theme-accent','accent'],['theme-background','background'],['theme-panel','panel']] as const)$<HTMLInputElement>(id).value=appearance[key];$<HTMLSelectElement>('settings-density').value=appearance.density;$<HTMLInputElement>('settings-font-size').value=String(appearance.fontSize);$('font-size-value').textContent=`${appearance.fontSize}px`;$<HTMLInputElement>('settings-reduced-motion').checked=appearance.reducedMotion;$<HTMLInputElement>('settings-show-members').checked=appearance.showMembers}
function openSettings(tab='profile'){if(!state)return;const user=state.user;$<HTMLInputElement>('settings-display-name').value=user.displayName;$<HTMLTextAreaElement>('settings-bio').value=user.bio;$<HTMLInputElement>('settings-avatar').value=user.avatar;$<HTMLSelectElement>('settings-status').value=user.status;$('settings-account-name').textContent=`Conectado como ${user.displayName} (${user.email})`;syncAppearanceControls();$(`settings-tab-${tab}`).click();show('settings-modal')}
function closeSettings(){hide('settings-modal');if(micTestStream){micTestStream.getTracks().forEach(track=>track.stop());micTestStream=null;if(micTestTimer!==null){clearInterval(micTestTimer);micTestTimer=null}if(micTestContext){void micTestContext.close();micTestContext=null}$<HTMLMeterElement>('mic-level').value=0;$('mic-test-status').textContent='Teste desligado';$('test-mic').textContent='Testar microfone'}if(cameraTestStream){cameraTestStream.getTracks().forEach(track=>track.stop());cameraTestStream=null;const preview=$<HTMLVideoElement>('camera-preview');preview.srcObject=null;preview.hidden=true;$('test-camera').textContent='Testar câmera'}}
function setupContextMenu(){const menu=document.createElement('div');menu.id='app-context-menu';menu.className='app-context-menu hidden';menu.setAttribute('role','menu');document.body.append(menu);const close=()=>menu.classList.add('hidden');const copy=async (value:string)=>{try{await navigator.clipboard.writeText(value);toast('Copiado.')}catch{toast('Não foi possível copiar neste navegador.')}};
  document.addEventListener('contextmenu',event=>{const target=event.target as HTMLElement;if(!target.closest('#app')||target.closest('input,textarea,select,[contenteditable="true"]'))return;event.preventDefault();if(!state)return;let actions:Array<[string,()=>void]>=[];const channelEl=target.closest<HTMLElement>('.channel[data-channel-id]')||target.closest<HTMLElement>('.channel-row')?.querySelector<HTMLElement>('.channel[data-channel-id]');const communityEl=target.closest<HTMLElement>('.server-pill[data-community-id]');const memberEl=target.closest<HTMLElement>('.member[data-user-id]');const messageEl=target.closest<HTMLElement>('.message[data-message-id]');
    if(channelEl){const channel=state.channels.find(item=>item.id===channelEl.dataset.channelId);if(channel){actions=[['Abrir canal',()=>void selectChannel(channel.id)],['Abrir chat',()=>void selectChannel(channel.id,true)],['Copiar nome do canal',()=>void copy(channel.name)]]}}
    else if(communityEl){const community=state.communities.find(item=>item.id===communityEl.dataset.communityId);if(community){actions=[['Abrir comunidade',()=>selectServer(community.id)],['Copiar nome',()=>void copy(community.name)]];if(community.ownerId===state.user.id)actions.push(['Gerenciar comunidade',()=>{selectServer(community.id);manageServer()}])}}
    else if(memberEl){const userId=memberEl.dataset.userId;const member=state.memberships.find(item=>item.userId===userId&&item.communityId===activeServer);if(member){const name=member.user?.displayName||'Pessoa';actions=[['Copiar nome',()=>void copy(name)]];if(userId!==state.user.id)actions.unshift(['Opções do membro',()=>memberActions(userId!,name)])}}
    else if(messageEl){const message=state.messages.find(item=>item.id===messageEl.dataset.messageId);if(message){actions=[['Copiar mensagem',()=>void copy(message.text)],['Copiar nome de quem enviou',()=>void copy(message.name||state?.memberships.find(item=>item.userId===message.userId)?.user?.displayName||'Pessoa')]]}}
    else if(target.closest('#call-stage')){actions=[['Abrir chat do canal',()=>{chatOpen=true;renderApp()}],['Áudio e vídeo',()=>openSettings('audio')],['Compartilhar tela',()=>void openShare()]]}
    else actions=[['Ir para o início',()=>selectServer(null)],['Criar comunidade',createServer],['Abrir configurações',()=>openSettings()]];
    menu.replaceChildren();for(const [label,action] of actions){const item=btn(label,()=>{close();action()});item.setAttribute('role','menuitem');menu.append(item)}menu.classList.remove('hidden');menu.style.left=`${Math.max(8,Math.min(event.clientX,innerWidth-menu.offsetWidth-8))}px`;menu.style.top=`${Math.max(8,Math.min(event.clientY,innerHeight-menu.offsetHeight-8))}px`;menu.querySelector<HTMLButtonElement>('button')?.focus()});
  document.addEventListener('pointerdown',event=>{if(!menu.contains(event.target as Node))close()});document.addEventListener('keydown',event=>{if(event.key==='Escape')close()});document.addEventListener('scroll',close,true)}
prepareCallLayout();
setupContextMenu();
function toast(message:string){const el=$('toast');el.textContent=message;el.classList.remove('hidden');setTimeout(()=>el.classList.add('hidden'),5000)}
function avatar(name:string){const el=document.createElement('div');el.className='avatar';el.textContent=(name[0]||'?').toUpperCase();return el}
function btn(label:string,action:()=>void,className=''){const el=document.createElement('button');el.textContent=label;el.className=className;el.onclick=action;return el}
function show(id:string){$(id).classList.remove('hidden')}function hide(id:string){$(id).classList.add('hidden')}
function request(type:string,fields:Record<string,unknown>={}){return new Promise<any>((resolve,reject)=>{if(socket?.readyState!==WebSocket.OPEN){reject(Error('Serviço online desconectado. Aguarde a reconexão.'));return}const id=++requestSeq;pending.set(id,{resolve,reject});socket.send(JSON.stringify({type,requestId:id,...fields}));setTimeout(()=>{const task=pending.get(id);if(task){pending.delete(id);task.reject(Error('Tempo de resposta esgotado.'))}},15000)})}
function setAuthMode(mode:'login'|'register'){authMode=mode;$('auth-title').textContent=mode==='login'?'Entre na sua conta':'Crie sua conta';$('auth-subtitle').textContent=mode==='login'?'Continue de onde parou, com seus servidores e amigos.':'Seu perfil vem antes de qualquer comunidade.';$('auth-submit').textContent=mode==='login'?'Entrar':'Criar conta';$('auth-switch').textContent=mode==='login'?'Criar conta':'Já tenho conta';$('auth-switch-text').textContent=mode==='login'?'Ainda não tem uma conta?':'Já possui uma conta?';for(const id of ['display-label','username-label'])$(id).classList.toggle('hidden',mode==='login');$<HTMLInputElement>('password-input').autocomplete=mode==='login'?'current-password':'new-password';$<HTMLInputElement>('username-input').required=mode==='register';$<HTMLInputElement>('display-input').required=mode==='register';$('auth-error').textContent=''}
function enterApp(){hide('loading');hide('auth');show('app');renderApp()}
function showAuth(message=''){hide('loading');hide('app');show('auth');$('auth-error').textContent=message;$<HTMLButtonElement>('auth-submit').disabled=socket?.readyState!==WebSocket.OPEN}
async function signOut(){try{if(socket?.readyState===WebSocket.OPEN)await request('logout')}catch(error){console.warn('Não foi possível revogar a sessão no servidor:',error)}finally{releasePtt();rtc.shutdown();updateMicButton();micTestStream?.getTracks().forEach(track=>track.stop());micTestStream=null;if(micTestTimer!==null){clearInterval(micTestTimer);micTestTimer=null}if(micTestContext){void micTestContext.close();micTestContext=null}cameraTestStream?.getTracks().forEach(track=>track.stop());cameraTestStream=null;const cameraPreview=$<HTMLVideoElement>('camera-preview');cameraPreview.srcObject=null;cameraPreview.hidden=true;token=null;state=null;activeServer=null;activeChannel=null;chatOpen=false;voicePresence=[];restoredSelection=false;localStorage.removeItem('orbiter-last-server');localStorage.removeItem('orbiter-last-channel');await window.orbita.clearSession();$<HTMLInputElement>('password-input').value='';setAuthMode('login');showAuth()}}
function acceptAuth(data:any){token=data.token;if(token)void window.orbita.writeSession(token);enterApp()}
function handleMessage(msg:any){if(msg.type==='result'){const item=pending.get(msg.requestId);if(item){pending.delete(msg.requestId);msg.ok?item.resolve(msg.data):item.reject(Error(msg.error||'Ação falhou.'))}return}
  if(msg.type==='state'){const next=msg.data as State;state=next;voicePresence=(msg.data.voicePresence||[]) as VoiceParticipant[];if(!restoredSelection){restoredSelection=true;const lastServer=localStorage.getItem('orbiter-last-server'),lastChannel=localStorage.getItem('orbiter-last-channel');if(next.communities.some(c=>c.id===lastServer)){activeServer=lastServer;if(next.channels.some(c=>c.id===lastChannel&&c.communityId===activeServer)){activeChannel=lastChannel;void request('select_channel',{channelId:lastChannel}).then(joined=>{for(const p of joined.peers)rtc.add(p.id)}).catch(()=>{})}}}if(activeServer&&!next.communities.some(c=>c.id===activeServer)){activeServer=null;activeChannel=null;rtc.clear()}if(activeChannel&&!next.channels.some(c=>c.id===activeChannel)){activeChannel=null;rtc.clear()}if(token)enterApp();else renderApp();return}
  if(msg.type==='voice_presence'){voicePresence=msg.participants;renderChannels();return}
  if(msg.type==='google_auth'){acceptAuth(msg);return}
  if(msg.type==='message'){if(state){state.messages.push(msg.message);if(msg.message.channelId===activeChannel)renderMessages()}return}
  if(msg.type==='signal'){void rtc.receive(msg.from,msg.data as Signal);return}
  if(msg.type==='peer_joined'){if(msg.id!==state?.user.id)rtc.add(msg.id);renderMembers();return}
  if(msg.type==='peer_left'){rtc.remove(msg.id);renderMembers()}
}
async function loadIceConfig(){try{const config=await window.orbita.iceConfig();if(!Array.isArray(config.iceServers)||!config.iceServers.some((server:RTCIceServer)=>[server.urls].flat().some(url=>url.startsWith('turn:')||url.startsWith('turns:'))))throw Error('Servidor TURN não disponível');rtc.configureIceServers(config.iceServers);return true}catch(error){console.warn('TURN não carregado:',error);toast('TURN indisponível. A chamada entre redes diferentes pode falhar.');return false}}
function scheduleReconnect(){if(reconnectTimer!==null||connecting)return;reconnectTimer=window.setTimeout(()=>{reconnectTimer=null;void connectBackend()},3000)}
async function connectBackend(){if(connecting||socket?.readyState===WebSocket.OPEN)return;connecting=true;try{
  const url=backendAddress||await window.orbita.backendUrl();backendAddress=url;
  if(!/^ws:\/\/(127\.0\.0\.1|localhost)(:\d+)?$/.test(url))$('google-btn').classList.add('hidden');
  const candidate=new WebSocket(url);
  await new Promise<void>((resolve,reject)=>{const timer=window.setTimeout(()=>{candidate.close();reject(Error('Tempo de conexão esgotado.'))},15000);candidate.onopen=()=>{clearTimeout(timer);resolve()};candidate.onerror=()=>{clearTimeout(timer);candidate.close();reject(Error('Serviço indisponível.'))};candidate.onclose=()=>{clearTimeout(timer);reject(Error('Conexão encerrada.'))}});
  socket=candidate;
  candidate.onmessage=e=>{try{handleMessage(JSON.parse(e.data))}catch(error){console.error(error)}};
  candidate.onclose=()=>{if(socket!==candidate)return;socket=null;voicePresence=[];restoredSelection=false;renderChannels();releasePtt();rtc.shutdown();updateMicButton();for(const task of pending.values())task.reject(Error('Conexão encerrada.'));pending.clear();$('connection-label').textContent='Reconectando';toast('Conexão perdida. Tentando reconectar…');if(!state)showAuth('Conexão perdida. Tentando reconectar…');scheduleReconnect()};
  void loadIceConfig();
  token=token||await window.orbita.readSession();
  if(token){try{await request('resume',{token});return}catch{if(socket?.readyState!==WebSocket.OPEN)return;token=null;state=null;await window.orbita.clearSession()}}
  showAuth();
}catch(error){if(!state)showAuth('Serviço online indisponível. Tentando reconectar…');else $('connection-label').textContent='Reconectando';console.warn('Conexão com o Orbiter:',error)}finally{connecting=false;if(socket?.readyState!==WebSocket.OPEN)scheduleReconnect()}}
function navigate(render:()=>void){const page=document as Document&{startViewTransition?:(update:()=>void)=>{finished:Promise<void>}};if(!appearance.reducedMotion&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches&&page.startViewTransition){void page.startViewTransition(render).finished.catch(()=>{})}else render()}
function closeMobileDrawers(){$('app').classList.remove('mobile-nav-open','mobile-members-open');$('mobile-menu-btn').setAttribute('aria-expanded','false');$('mobile-members-btn').setAttribute('aria-expanded','false')}
function selectServer(id:string|null){releasePtt();void request('leave_channel').catch(e=>toast(e.message));rtc.clear();activeServer=id;activeChannel=null;chatOpen=false;closeMobileDrawers();if(id)localStorage.setItem('orbiter-last-server',id);else localStorage.removeItem('orbiter-last-server');localStorage.removeItem('orbiter-last-channel');navigate(renderApp)}
async function selectChannel(id:string,openChat=false){if(!state?.channels.some(c=>c.id===id&&c.communityId===activeServer))return;releasePtt();rtc.clear();activeChannel=id;chatOpen=openChat;closeMobileDrawers();localStorage.setItem('orbiter-last-channel',id);navigate(renderApp);await loadIceConfig();try{const joined=await request('select_channel',{channelId:id});if(activeChannel!==id)return;for(const p of joined.peers)rtc.add(p.id)}catch(e){toast((e as Error).message)}}
function renderRail(){const rail=$('server-rail');rail.replaceChildren();for(const community of state?.communities||[]){const item=btn((community.icon||community.name[0]||'?').slice(0,2),()=>selectServer(community.id),'server-pill'+(activeServer===community.id?' active':''));item.title=community.name;item.dataset.communityId=community.id;rail.append(item)}$('home-btn').classList.toggle('active',!activeServer)}
function renderChannels(){const text=$('channels'),voice=$('voice-channels');text.replaceChildren();voice.replaceChildren();const community=state?.communities.find(c=>c.id===activeServer);$('community-title').textContent=community?.name||'Início';const owned=community?.ownerId===state?.user.id;for(const id of ['community-menu','add-text','add-voice'])$(id).classList.toggle('hidden',!owned);
  for(const channel of state?.channels.filter(c=>c.communityId===activeServer)||[]){const item=btn(`${channel.type==='voice'?'◖':'#'}  ${channel.name}`,()=>void selectChannel(channel.id),'channel'+(activeChannel===channel.id?' active':''));item.dataset.channelId=channel.id;const row=document.createElement('div');row.className='channel-row';const chat=btn('💬',()=>{if(activeChannel===channel.id){chatOpen=!chatOpen;renderApp()}else void selectChannel(channel.id,true)},'channel-chat');chat.title=`${activeChannel===channel.id&&chatOpen?'Fechar':'Abrir'} chat de ${channel.name}`;chat.setAttribute('aria-label',chat.title);row.append(item,chat);(channel.type==='voice'?voice:text).append(row);if(channel.type==='voice'){const list=document.createElement('div');list.className='voice-participants';list.dataset.channelId=channel.id;list.setAttribute('aria-label',`Pessoas em ${channel.name}`);for(const participant of voicePresence.filter(p=>p.channelId===channel.id)){const user=state?.memberships.find(m=>m.communityId===channel.communityId&&m.userId===participant.userId)?.user;const name=user?.displayName||'Pessoa';const memberRow=document.createElement('div');memberRow.className='voice-participant';memberRow.dataset.userId=participant.userId;const label=document.createElement('span');label.textContent=name+(participant.userId===state?.user.id?' (você)':'');memberRow.append(avatar(name),label);list.append(memberRow)}voice.append(list)}}}
function renderApp(){if(!state)return;const user=state.user;$('own-name').textContent=user.displayName;$('own-avatar').textContent=(user.avatar||user.displayName[0]||'?').slice(0,2);$('connection-label').textContent=user.status==='invisible'?'Invisível':user.status==='away'?'Ausente':user.status==='busy'?'Ocupado':'Online';renderRail();renderChannels();const channel=state.channels.find(c=>c.id===activeChannel);$('channel-title').textContent=channel?.name||(!activeServer?'Início':state.communities.find(c=>c.id===activeServer)?.name||'Servidor');$('channel-icon').textContent=channel?.type==='voice'?'◖':channel?'#':'';$('channel-icon').classList.toggle('brand-mark',!channel);$('top-description').textContent=channel?'Converse com os membros desta comunidade':'Seu espaço no Orbiter';const hasChannel=!!channel;$('message-form').classList.toggle('hidden',!hasChannel);$('right-panel').classList.toggle('hidden',!hasChannel);$('call-stage').classList.toggle('hidden',!hasChannel);document.querySelector('.conversation')?.classList.toggle('hidden',hasChannel&&!chatOpen);document.querySelector('.content')?.classList.toggle('has-channel',hasChannel);document.querySelector('.content')?.classList.toggle('chat-open',hasChannel&&chatOpen);$('chat-toggle').classList.toggle('hidden',!hasChannel);$('chat-toggle').classList.toggle('active',chatOpen);$('chat-toggle').title=chatOpen?'Fechar chat do canal':'Abrir chat do canal';$('chat-toggle').setAttribute('aria-label',$('chat-toggle').title);$('mobile-members-btn').classList.toggle('hidden',!hasChannel);$('call-title').textContent=channel?.name||'';renderMessages();renderMembers();if(!activeServer)$('online-count').textContent='● Pronto para conversar'}
function empty(title:string,description:string,actions:Array<[string,()=>void]>){const root=document.createElement('div');root.className='empty-state';const symbol=document.createElement('div');symbol.className='symbol';symbol.textContent='✦';const h=document.createElement('h2');h.textContent=title;const p=document.createElement('p');p.textContent=description;const row=document.createElement('div');row.className='empty-actions';for(const [label,action] of actions)row.append(btn(label,action));root.append(symbol,h,p,row);return root}
function renderHome(box:HTMLElement){if(!state)return;box.classList.add('home-messages');const home=document.createElement('div');home.className='home-screen';const hero=document.createElement('section');hero.className='home-hero';hero.innerHTML='<div class="home-glow" aria-hidden="true"><span>✦</span></div><div class="home-hero-copy"><span class="eyebrow">BEM-VINDO AO SEU ESPAÇO</span><h1></h1><p>Converse, reúna seu time e compartilhe o que importa. Escolha uma comunidade para começar.</p><div class="home-hero-actions"></div></div>';
  hero.querySelector('h1')!.textContent=`Olá, ${state.user.displayName.split(' ')[0]||'você'}.`;
  const heroActions=hero.querySelector<HTMLElement>('.home-hero-actions')!;heroActions.append(btn('＋ Criar comunidade',createServer,'home-primary'),btn('Entrar com convite',joinInvite,'home-secondary'));
  const overview=document.createElement('div');overview.className='home-overview';overview.innerHTML='<div><span>COMUNIDADES</span><strong></strong></div><div><span>CANAIS DISPONÍVEIS</span><strong></strong></div><div><span>CONEXÃO</span><strong>Pronto para entrar</strong></div>';
  overview.querySelectorAll('strong')[0].textContent=String(state.communities.length);overview.querySelectorAll('strong')[1].textContent=String(state.channels.length);
  const section=document.createElement('section');section.className='home-section';section.innerHTML='<div class="home-section-head"><div><span class="eyebrow">ACESSO RÁPIDO</span><h2>Suas comunidades</h2></div></div><div class="home-communities"></div>';
  const cards=section.querySelector<HTMLElement>('.home-communities')!;
  if(state.communities.length){for(const community of state.communities){const card=btn('',()=>selectServer(community.id),'home-community');const icon=document.createElement('span');icon.className='home-community-icon';icon.textContent=(community.icon||community.name[0]||'✦').slice(0,2);const details=document.createElement('span');details.className='home-community-copy';const name=document.createElement('strong');name.textContent=community.name;const count=document.createElement('small');count.textContent=`${state.channels.filter(channel=>channel.communityId===community.id).length} canais`;details.append(name,count);const arrow=document.createElement('span');arrow.className='home-community-arrow';arrow.textContent='↗';card.append(icon,details,arrow);cards.append(card)}}else{const starter=document.createElement('div');starter.className='home-starter';starter.innerHTML='<span>✦</span><strong>Sua primeira comunidade começa aqui.</strong><p>Crie um espaço para amigos ou entre em um com um convite.</p>';starter.append(btn('Criar comunidade',createServer,'home-secondary'));cards.append(starter)}
  home.append(hero,overview,section);box.append(home)}
function renderServerLanding(box:HTMLElement){if(!state)return;box.classList.add('home-messages');const community=state.communities.find(item=>item.id===activeServer);if(!community)return;const root=document.createElement('div');root.className='server-landing';const intro=document.createElement('div');intro.className='server-landing-intro';intro.innerHTML='<span class="eyebrow">COMUNIDADE</span><div class="server-landing-mark"></div><h1></h1><p></p>';intro.querySelector('.server-landing-mark')!.textContent=(community.icon||community.name[0]||'✦').slice(0,2);intro.querySelector('h1')!.textContent=community.name;intro.querySelector('p')!.textContent=community.description||'Escolha um canal para conversar ou entrar em uma sala de voz.';root.append(intro);
  const heading=document.createElement('h2');heading.textContent='Entre na conversa';root.append(heading);const cards=document.createElement('div');cards.className='server-channel-list';for(const channel of state.channels.filter(item=>item.communityId===community.id)){const card=btn('',()=>void selectChannel(channel.id,channel.type==='text'),'server-channel-card');const mark=document.createElement('span');mark.textContent=channel.type==='voice'?'◖':'#';const name=document.createElement('strong');name.textContent=channel.name;const detail=document.createElement('small');detail.textContent=channel.type==='voice'?'Sala de voz e tela':'Canal de texto';card.append(mark,name,detail);cards.append(card)}if(!cards.children.length)cards.append(empty('Ainda não há canais','Crie um canal para começar.',[['Criar canal',()=>createChannel('text')]]));root.append(cards);box.append(root)}
function renderMessages(){const box=$('messages');box.replaceChildren();box.classList.remove('home-messages');if(!state)return;if(!activeServer){renderHome(box);return}
  if(!activeChannel){renderServerLanding(box);return}
  const list=state.messages.filter(m=>m.channelId===activeChannel);if(!list.length){box.append(empty('Comece a conversa','Ainda não há mensagens neste canal.',[]));return}
  for(const message of list){if(blocked.has(message.userId))continue;const user=state.memberships.find(m=>m.userId===message.userId)?.user;const name=message.name||user?.displayName||'Pessoa';const row=document.createElement('div');row.className='message';row.dataset.messageId=message.id;row.dataset.userId=message.userId;const body=document.createElement('div');body.className='message-body';const head=document.createElement('div');head.className='message-head';const strong=document.createElement('strong');strong.textContent=name;const time=document.createElement('time');time.textContent=new Date(message.at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});const content=document.createElement('div');content.className='message-text';content.textContent=message.text;head.append(strong,time);body.append(head,content);row.append(avatar(name),body);box.append(row)}box.scrollTop=box.scrollHeight}
function renderMembers(){const box=$('members');box.replaceChildren();if(!state||!activeServer)return;const community=state.communities.find(c=>c.id===activeServer);for(const member of state.memberships.filter(m=>m.communityId===activeServer)){const row=document.createElement('div');row.className='member';row.dataset.userId=member.userId;const name=member.user?.displayName||'Pessoa';const label=document.createElement('span');label.textContent=name+(member.userId===state.user.id?' (você)':'');row.append(avatar(name),label);if(member.userId!==state.user.id){row.append(btn('⋯',()=>memberActions(member.userId,name),'subtle'))}box.append(row)}$('online-count').textContent=`● ${state.memberships.filter(m=>m.communityId===activeServer).length} membros`;$('call-status').textContent=activeChannel?'Áudio e tela são compartilhados apenas com quem está neste canal.':'Escolha um canal para começar.'}
function layoutRemoteTiles(){const box=$('remote-media');const videoCount=box.querySelectorAll(':scope>div.video-tile').length;box.classList.toggle('has-video',videoCount>0);box.classList.toggle('has-multiple-videos',videoCount>1);let order=0;box.querySelectorAll<HTMLElement>(':scope>div:not(.video-tile)').forEach(tile=>tile.style.setProperty('--peer-order',String(order++)))}
function renderRemote(id:string,stream:MediaStream|null){const box=$('remote-media');let el=document.getElementById(`media-${id}`);if(!stream){el?.remove();layoutRemoteTiles();return}if(!el){el=document.createElement('div');el.id=`media-${id}`;box.append(el)}el.replaceChildren();const hasVideo=stream.getVideoTracks().length>0;el.classList.toggle('video-tile',hasVideo);const name=state?.memberships.find(m=>m.userId===id)?.user?.displayName||'Pessoa';el.append(avatar(name));const p=document.createElement('p');p.textContent=name;el.append(p);const audio=document.createElement('audio');audio.autoplay=true;audio.setAttribute('playsinline','');audio.srcObject=stream;el.append(audio);const listen=btn('▶ Ativar som',()=>{void audio.play().then(()=>{listen.hidden=true}).catch(()=>toast('Toque novamente para liberar o áudio neste navegador.'))},'media-listen');listen.hidden=true;el.append(listen);audio.onloadedmetadata=()=>{void audio.play().catch(()=>{listen.hidden=false})};void setOutputDevice();if(hasVideo){const video=document.createElement('video');video.autoplay=true;video.muted=true;video.playsInline=true;video.srcObject=stream;el.append(video);void video.play().catch(()=>{});const fullscreen=btn('⛶ Tela cheia',()=>{const mobileVideo=video as HTMLVideoElement&{webkitEnterFullscreen?:()=>void};if(video.requestFullscreen)void video.requestFullscreen().catch(()=>{});else mobileVideo.webkitEnterFullscreen?.()},'media-fullscreen');fullscreen.title='Assistir transmissão em tela cheia';el.append(fullscreen)}layoutRemoteTiles()}
type Field={key:string;label:string;value?:string;type?:'text'|'textarea'|'select';options?:Array<[string,string]>};
function action(title:string,description:string,fields:Field[],confirm:string,run:(values:Record<string,string>)=>Promise<void>){$('action-title').textContent=title;$('action-description').textContent=description;$('action-confirm').textContent=confirm;$('action-error').textContent='';const root=$('action-fields');root.replaceChildren();const controls=new Map<string,HTMLInputElement|HTMLTextAreaElement|HTMLSelectElement>();for(const field of fields){const label=document.createElement('label');label.className='field';label.textContent=field.label;let control:HTMLInputElement|HTMLTextAreaElement|HTMLSelectElement;if(field.type==='textarea')control=document.createElement('textarea');else if(field.type==='select'){const select=document.createElement('select');for(const [value,text] of field.options||[])select.add(new Option(text,value));control=select}else control=document.createElement('input');if(field.value!==undefined)control.value=field.value;label.append(control);root.append(label);controls.set(field.key,control)}$('action-confirm').onclick=async()=>{const values=Object.fromEntries([...controls].map(([key,control])=>[key,control.value.trim()]));hide('action-modal');try{await run(values)}catch(e){$('action-error').textContent=(e as Error).message;show('action-modal')}};show('action-modal')}
function createServer(){action('Criar meu servidor','Comunidades são espaços lógicos associados ao seu perfil. Você será o proprietário.',[{key:'name',label:'Nome do servidor'},{key:'description',label:'Descrição',type:'textarea'},{key:'icon',label:'Ícone (emoji ou texto curto)'},{key:'rules',label:'Regras da comunidade',type:'textarea'},{key:'privacy',label:'Acesso',type:'select',options:[['invite','Por convite'],['approval','Aprovação manual (em desenvolvimento)']]}],'Criar servidor',async v=>{const created=await request('create_server',v);selectServer(created.id);toast('Servidor criado com # geral e canal de voz.')})}
function joinInvite(){action('Entrar com convite','Cole o código de convite enviado pelo administrador.',[{key:'code',label:'Código ou link de convite'}],'Entrar',async v=>{const code=v.code.split('/').pop()||v.code;const joined=await request('invite_join',{code});selectServer(joined.id);toast('Você entrou na comunidade.')})}
function addFriend(){action('Adicionar amigo','Solicite amizade usando o nome de usuário.',[{key:'username',label:'Nome de usuário'}],'Enviar solicitação',async v=>{await request('friend_request',v);toast('Solicitação enviada.')})}
function createChannel(type:'text'|'voice'){if(!activeServer)return;const categories=state?.categories.filter(c=>c.communityId===activeServer)||[];action(`Criar canal de ${type==='text'?'texto':'voz'}`,'O canal ficará disponível aos membros desta comunidade.',[{key:'name',label:'Nome do canal'},...(categories.length?[{key:'categoryId',label:'Categoria',type:'select' as const,options:[['','Sem categoria'] as [string,string],...categories.map(c=>[c.id,c.name] as [string,string])]}]:[])],'Criar canal',async v=>{await request('create_channel',{communityId:activeServer,name:v.name,channelType:type,categoryId:v.categoryId||null});toast('Canal criado.')})}
function memberActions(id:string,name:string){if(!state||!activeServer)return;const owner=state.communities.find(c=>c.id===activeServer)?.ownerId===state.user.id;const roles=state.roles.filter(r=>r.communityId===activeServer);const options:Field[]=[{key:'action',label:`Ação para ${name}`,type:'select',options:[['block','Bloquear nesta sessão'],['report','Denunciar'],...(owner?[['kick','Expulsar'],['ban','Banir'],...(roles.length?[['role','Atribuir cargo']]:[])] as Array<[string,string]>:[])]},{key:'reason',label:'Motivo da denúncia',value:''},...(roles.length&&owner?[{key:'roleId',label:'Cargo',type:'select' as const,options:roles.map(r=>[r.id,r.name] as [string,string])}]:[])];action('Gerenciar membro','Denúncias são registradas pelo operador do backend.',options,'Aplicar',async v=>{if(v.action==='block'){blocked.add(id);rtc.remove(id);renderMessages()}else if(v.action==='report')await request('report',{target:id,reason:v.reason});else if(v.action==='role')await request('assign_role',{communityId:activeServer,targetId:id,roleId:v.roleId});else await request(v.action==='ban'?'ban_member':'kick_member',{communityId:activeServer,targetId:id});toast('Ação registrada.')})}
function manageServer(){
  if(!activeServer||!state)return;
  const community=state.communities.find(c=>c.id===activeServer);if(!community||community.ownerId!==state.user.id)return;
  action('Gerenciar servidor','Convites, categorias, cargos e canais da sua comunidade.',[{key:'task',label:'Ação',type:'select',options:[['invite','Gerar convite'],['revoke','Revogar convite'],['category','Criar categoria'],['role','Criar cargo'],['rename','Renomear canal atual'],['delete-channel','Excluir canal atual'],['delete-server','Excluir servidor']]}],'Continuar',async v=>{
    const id=activeServer!;
    if(v.task==='invite'){const invite=await request('invite_create',{communityId:id,hours:24});action('Convite criado','Compartilhe este código. Ele expira em 24 horas.',[{key:'code',label:'Código de convite',value:invite.code},...(invite.url?[{key:'url',label:'Link de convite',value:invite.url}]:[])],'Fechar',async()=>{});return}
    if(v.task==='revoke'){const list=state!.invites.filter(i=>i.communityId===id);if(!list.length)throw Error('Não há convites ativos.');action('Revogar convite','O código deixará de aceitar novas entradas.',[{key:'code',label:'Convite',type:'select',options:list.map(i=>[i.code,`${i.code.slice(0,8)}… · ${i.uses} usos`])}],'Revogar',async x=>{await request('invite_revoke',{code:x.code})});return}
    if(v.task==='category'){action('Criar categoria','Organize canais por assunto.',[{key:'name',label:'Nome'}],'Criar',async x=>{await request('create_category',{communityId:id,name:x.name})});return}
    if(v.task==='role'){action('Criar cargo','Defina as permissões administrativas deste cargo.',[{key:'name',label:'Nome'},{key:'preset',label:'Permissões',type:'select',options:[['none','Nenhuma'],['channels','Gerenciar canais'],['members','Gerenciar membros'],['invites','Gerenciar convites'],['all','Todas as permissões']]}],'Criar',async x=>{const all=['manage_channels','manage_members','manage_roles','manage_invites'];const permissions=x.preset==='all'?all:x.preset==='channels'?[all[0]]:x.preset==='members'?[all[1]]:x.preset==='invites'?[all[3]]:[];await request('create_role',{communityId:id,name:x.name,permissions})});return}
    if(v.task==='rename'){if(!activeChannel)throw Error('Selecione um canal.');action('Renomear canal','', [{key:'name',label:'Novo nome'}],'Salvar',async x=>{await request('edit_channel',{channelId:activeChannel,name:x.name})});return}
    if(v.task==='delete-channel'){if(!activeChannel||!confirm('Excluir este canal e suas mensagens?'))return;await request('delete_channel',{channelId:activeChannel});activeChannel=null;return}
    if(v.task==='delete-server'){if(!confirm(`Excluir permanentemente ${community.name} e seus canais?`))return;await request('delete_server',{communityId:id});activeServer=null;activeChannel=null}
  });
}
function profileSettings(){openSettings('profile')}
function showFriends(){activeServer=null;activeChannel=null;renderApp();const box=$('messages');box.replaceChildren();const root=document.createElement('div');root.className='empty-state';const h=document.createElement('h2');h.textContent='Amigos';root.append(h);for(const item of state?.friends||[]){const p=document.createElement('p');p.textContent=`${item.user?.displayName||'Usuário'} · ${item.accepted?'Amigo':item.to===state?.user.id?'Solicitação recebida':'Solicitação enviada'}`;root.append(p);if(!item.accepted&&item.to===state?.user.id)root.append(btn('Aceitar',()=>void request('friend_accept',{fromId:item.from}).catch(e=>toast(e.message))))}root.append(btn('Adicionar amigo',addFriend,'primary'));box.append(root)}
async function openShare(){if(!activeChannel){toast('Escolha um canal.');return}if(rtc.sharing){rtc.stopShare();$('share-btn').classList.remove('active');$('share-btn').querySelector('span')!.textContent='Compartilhar tela';$<HTMLVideoElement>('local-preview').srcObject=null;$('local-preview').hidden=true;return}if(!navigator.mediaDevices?.getDisplayMedia){toast('Este navegador não oferece captura de tela. Você ainda pode assistir a transmissões aqui.');return}const box=$('sources');box.replaceChildren();try{for(const source of await window.orbita.sources())box.append(btn(source.name,()=>void startShare(source.id),'source'));show('share-modal')}catch{toast('Não foi possível listar telas e janelas.')}}
async function startShare(id:string){hide('share-modal');if(!confirm('Iniciar transmissão da fonte selecionada para membros deste canal?'))return;const quality=$<HTMLSelectElement>('quality').value;const [height,fps]=quality==='1080-60'?[1080,60]:quality==='1080'?[1080,30]:[720,30];try{const stream=await rtc.share(id,$<HTMLInputElement>('system-audio').checked,height,fps,window.orbita.select);const video=$<HTMLVideoElement>('local-preview');video.srcObject=stream;video.hidden=false;$('share-btn').classList.add('active');$('share-btn').querySelector('span')!.textContent='Encerrar transmissão'}catch(e){toast('Captura cancelada ou indisponível.');console.error(e)}}
$<HTMLFormElement>('auth-form').onsubmit=async e=>{e.preventDefault();const data={email:$<HTMLInputElement>('email-input').value,password:$<HTMLInputElement>('password-input').value,username:$<HTMLInputElement>('username-input').value,displayName:$<HTMLInputElement>('display-input').value};try{const result=await request(authMode,data);acceptAuth(result)}catch(err){$('auth-error').textContent=(err as Error).message}};
$('auth-switch').onclick=()=>setAuthMode(authMode==='login'?'register':'login');$('google-btn').onclick=async()=>{try{const value=await request('google_start');await window.orbita.openOAuth(value.url);$('auth-error').textContent='Conclua a autenticação no navegador.'}catch(e){$('auth-error').textContent=(e as Error).message}};
$('home-btn').onclick=()=>selectServer(null);$('create-server-btn').onclick=()=>action('Adicionar servidor','Escolha como deseja começar.',[{key:'choice',label:'Opção',type:'select',options:[['create','Criar meu servidor'],['join','Entrar com convite']]}],'Continuar',async v=>{v.choice==='create'?createServer():joinInvite()});$('friends-btn').onclick=showFriends;$('community-menu').onclick=manageServer;$('add-text').onclick=()=>createChannel('text');$('add-voice').onclick=()=>createChannel('voice');$('settings-btn').onclick=profileSettings;$('settings-btn').title='Abrir configurações';
$('action-cancel').onclick=()=>hide('action-modal');$<HTMLFormElement>('message-form').onsubmit=async e=>{e.preventDefault();if(!activeChannel)return;const input=$<HTMLInputElement>('message-input'),text=input.value.trim();if(!text)return;try{await request('message_send',{channelId:activeChannel,text});input.value=''}catch(err){toast((err as Error).message)}};
$('mic-btn').onclick=async()=>{if(!activeChannel){toast('Escolha um canal.');return}if(micStarting)return;micStarting=true;try{if(rtc.micOn)releasePtt();await rtc.toggleMic($<HTMLSelectElement>('audio-input').value||undefined,!pttMode);updateMicButton()}catch{toast('Microfone não autorizado ou indisponível.')}finally{micStarting=false}};$('share-btn').onclick=()=>void openShare();$('share-cancel').onclick=()=>hide('share-modal');
void connectBackend();
let micTestStream:MediaStream|null=null,micTestContext:AudioContext|null=null,micTestTimer:number|null=null;
async function refreshAudioDevices(){const devices=await navigator.mediaDevices.enumerateDevices();for(const [id,kind] of [['audio-input','audioinput'],['audio-output','audiooutput'],['video-input','videoinput']] as const){const select=$<HTMLSelectElement>(id),previous=select.value;select.replaceChildren(new Option('Padrão do sistema',''));for(const device of devices.filter(d=>d.kind===kind))select.add(new Option(device.label||`${kind==='audioinput'?'Microfone':kind==='videoinput'?'Câmera':'Saída'} ${select.length}`,device.deviceId));select.value=Array.from(select.options).some(o=>o.value===previous)?previous:''}}
async function setOutputDevice(){const sink=$<HTMLSelectElement>('audio-output').value;for(const audio of Array.from(document.querySelectorAll<HTMLAudioElement>('#remote-media audio'))){if('setSinkId' in audio)try{await audio.setSinkId(sink)}catch(e){toast('Não foi possível usar esta saída de áudio.')}}}
$('refresh-audio').onclick=()=>void refreshAudioDevices().catch(e=>toast((e as Error).message));
$('audio-output').onchange=()=>void setOutputDevice();
$('test-output').onclick=async()=>{const context=new AudioContext(),destination=context.createMediaStreamDestination(),tone=context.createOscillator(),gain=context.createGain(),audio=new Audio();try{tone.frequency.value=440;gain.gain.value=0.08;tone.connect(gain).connect(destination);audio.srcObject=destination.stream;const sink=$<HTMLSelectElement>('audio-output').value;if(sink&&'setSinkId' in audio)await audio.setSinkId(sink);else if(sink)throw Error('Este navegador não permite escolher a saída de áudio.');await audio.play();tone.start();tone.stop(context.currentTime+0.4);await new Promise(resolve=>setTimeout(resolve,550))}catch(e){toast((e as Error).message||'Não foi possível testar a saída.')}finally{audio.pause();audio.srcObject=null;await context.close()}};
$('audio-input').onchange=()=>{if(rtc.micOn)toast('Desative e ative o microfone para usar o novo dispositivo.')};
void refreshAudioDevices().catch(()=>{});
$('test-mic').onclick=async()=>{if(micTestStream){micTestStream.getTracks().forEach(t=>t.stop());micTestStream=null;if(micTestTimer!==null)clearInterval(micTestTimer);await micTestContext?.close();micTestContext=null;$<HTMLMeterElement>('mic-level').value=0;$('mic-test-status').textContent='Teste desligado';$('test-mic').textContent='Testar microfone';return}try{micTestStream=await navigator.mediaDevices.getUserMedia({audio:$<HTMLSelectElement>('audio-input').value?{deviceId:{exact:$<HTMLSelectElement>('audio-input').value}}:true});await refreshAudioDevices();micTestContext=new AudioContext();const source=micTestContext.createMediaStreamSource(micTestStream),analyser=micTestContext.createAnalyser();source.connect(analyser);const samples=new Uint8Array(analyser.fftSize);micTestTimer=window.setInterval(()=>{analyser.getByteTimeDomainData(samples);let sum=0;for(const value of samples){const v=(value-128)/128;sum+=v*v}const level=Math.min(100,Math.round(Math.sqrt(sum/samples.length)*300));$<HTMLMeterElement>('mic-level').value=level;$('mic-test-status').textContent=level>5?'Microfone captando voz':'Fale para testar o microfone'},100);$('test-mic').textContent='Parar teste'}catch(e){toast('Não foi possível acessar o microfone.')}};
let cameraTestStream:MediaStream|null=null;
$('test-camera').onclick=async()=>{const preview=$<HTMLVideoElement>('camera-preview');if(cameraTestStream){cameraTestStream.getTracks().forEach(track=>track.stop());cameraTestStream=null;preview.srcObject=null;preview.hidden=true;$('test-camera').textContent='Testar câmera';return}try{const deviceId=$<HTMLSelectElement>('video-input').value;cameraTestStream=await navigator.mediaDevices.getUserMedia({video:deviceId?{deviceId:{exact:deviceId}}:true,audio:false});preview.srcObject=cameraTestStream;preview.hidden=false;await preview.play();await refreshAudioDevices();$('test-camera').textContent='Parar câmera'}catch(e){cameraTestStream?.getTracks().forEach(track=>track.stop());cameraTestStream=null;preview.srcObject=null;preview.hidden=true;toast('Não foi possível acessar a câmera. Verifique a permissão e o dispositivo escolhido.')}};



